E("G10_TB_§36_36_13_7", "$(\\sqrt{6x+8})'=\\frac{6}{2\\sqrt{6x+8}}=\\frac{3}{\\sqrt{6x+8}}$; ключ был неверным, а пояснения к вариантам опирались на корень четвёртой степени",
  k=r"$\dfrac{3}{\sqrt{6x+8}}$",
  dnew={0: (r"$\dfrac{1}{2\sqrt{6x+8}}$", "Ученик не умножил на производную внутренней функции $(6x+8)'=6$."),
        1: (r"$\dfrac{6}{\sqrt{6x+8}}$", "Ученик умножил на $6$, но потерял множитель $2$ в знаменателе формулы $(\\sqrt{u})'=\\frac{u'}{2\\sqrt{u}}$."),
        2: (r"$\dfrac{3}{2\sqrt{6x+8}}$", "Ученик сократил $6$ и $2$ как $\\frac{3}{2}$ и оставил двойку в знаменателе: $\\frac{6}{2\\sqrt{u}}=\\frac{3}{\\sqrt{u}}$.")})
